function hintPlan(l,current){let target=solve(l,current);if(target){let i=target.findIndex((t,j)=>{if(!t||current[j])return false;const trial=current.slice();trial[j]=t;return ruleOK(t,j,trial,l);});if(i<0)i=target.findIndex((t,j)=>t&&!current[j]);return i<0?null:{kind:'place',cell:i,type:target[i]};}const occupied=current.map((t,i)=>t?i:-1).filter(i=>i>=0).sort((a,b)=>Number(ruleOK(current[a],a,current,l))-Number(ruleOK(current[b],b,current,l)));for(const i of occupied){const trial=current.slice();trial[i]=null;if(solve(l,trial))return{kind:'move',cell:i,type:current[i]};}target=solve(l);const i=occupied.find(i=>current[i]!==target?.[i]);return i===undefined?null:{kind:'move',cell:i,type:current[i]};}

