class ChallengeClock {
 constructor(){this.elapsed=0;this.started=false;this.expired=false;}
 reset(){this.elapsed=0;this.started=false;this.expired=false;}
 checkExpired(goal,enabled){if(enabled&&this.started&&this.elapsed>=goal)this.expired=true;return this.expired;}
 start(){this.started=true;}
 tick(seconds,running){if(this.started&&running&&Number.isFinite(seconds)&&seconds>0)this.elapsed+=seconds;}
 goal(level,mode='auto'){return (mode==='auto'?(level<8?2:level<14?3:5):Number(mode))*60;}
 remaining(level,mode){return Math.max(0,Math.ceil(this.goal(level,mode)-this.elapsed));}
 label(level,mode){const n=this.remaining(level,mode);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
}

function attemptTimePenalty(scene){if(scene.dailyDate)return false;return scene.challengeClock.checkExpired(scene.challengeClock.goal(scene.level,Settings.data.timerDuration),Settings.data.timer);}

