Game.prototype.flyToBasket=function(items,{overlay=null,onCount=null}={}){if(items.length&&this.worldScreen?.classList.contains('map-screen'))AudioManager.effect('sfx_harvest');const target=document.querySelector(this.worldScreen?'.map-decoration-shelf .basket-button':'.harvest-overlay .basket-button');if(!target||Motion.reduced){onCount?.();return;}const baseCount=Number(target.querySelector('.basket-count')?.textContent)||0,r=target.getBoundingClientRect(),owner=overlay||document.createElement('div');if(!overlay){owner.className='collection-flight';Object.assign(owner.style,{position:'fixed',inset:0,pointerEvents:'none',zIndex:155});document.body.append(owner);}items.forEach((item,i)=>{const im=document.createElement('div');im.className='harvest-fruit';im.innerHTML=assetMarkup(item.type+'_adult',plantFallbackSVG(item.type,'adult'));for(const art of im.children)Object.assign(art.style,{width:'100%',height:'100%',objectFit:'contain',display:'block'});Object.assign(im.style,{position:'fixed',left:item.x+'px',top:item.y+'px',width:'46px',height:'46px',pointerEvents:'none'});owner.append(im);const dx=r.left+r.width/2-item.x-23,dy=r.top+r.height/2-item.y-23,delay=items.length>1?i/(items.length-1)*180:0;const a=im.animate?.([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.45}px,${dy*.35-65}px) scale(.8)`,opacity:1,offset:.5},{transform:`translate(${dx}px,${dy}px) scale(.18)`,opacity:0}],{duration:750,delay,fill:'forwards',easing:'ease-in-out'});if(overlay&&a)this.harvestAnimations.push(a);else a?.finished.then(()=>im.remove()).catch(()=>{});const step=()=>{if(!target.isConnected)return;const label=target.querySelector('.basket-count');if(label)fitBasketCount(label,baseCount+i+1);target.animate?.([{transform:'scale(1)'},{transform:'scale(1.08)'},{transform:'scale(1)'}],{duration:130});};const job=setTimeout(step,750+delay);if(overlay)this.harvestTimers.push(job);});const pulse=()=>{onCount?.();target.animate?.([{transform:'scale(1)'},{transform:'scale(1.1)'},{transform:'scale(1)'}],{duration:160});};if(overlay)this.harvestTimers.push(setTimeout(pulse,940));else setTimeout(()=>{pulse();owner.remove();},940);};
Game.prototype.harvest=function(){if(!this.active||this.finishing||this.modal)return;const overlay=document.createElement('div');overlay.className='harvest-overlay';overlay.setAttribute('role','button');overlay.setAttribute('aria-label',TEXT.skip);overlay.tabIndex=0;const skip=document.createElement('div');skip.className='harvest-skip';skip.textContent=TEXT.skip;overlay.append(skip);this.attachBasket(overlay);const target=overlay.querySelector('.basket-button');target.classList.add('harvest-collection-target');target.tabIndex=-1;target.setAttribute('aria-hidden','true');document.body.append(overlay);this.harvestOverlay=overlay;overlay.onclick=()=>this.finishHarvest();overlay.onkeydown=e=>{if(['Enter',' ','Escape'].includes(e.key))this.finishHarvest();};const box=$('game').getBoundingClientRect(),geo=tileGeometry(box.width,this.l.n),items=[];for(const [i,t]of this.types().entries())if(t){const p=geo.cells[i];items.push({type:t,x:box.left+p.x+geo.tile/2-23,y:box.top+p.y+geo.tile*.35});}const badge=overlay.querySelector('.basket-count'),final=Rewards.total(),start=final-this.harvestAdded;if(badge)fitBasketCount(badge,start);this.flyToBasket(items,{overlay,onCount:()=>this.refreshBasket()});overlay.focus({preventScroll:true});};
const rewardsClearHarvest=Game.prototype.clearHarvest;Game.prototype.clearHarvest=function(){rewardsClearHarvest.call(this);for(const v of this.views?.values()||[])v.restoreColor();this.refreshBasket();};
const rewardsPanel=Game.prototype.renderHarvestPanel;Game.prototype.renderHarvestPanel=function(){
 if(this.dailyDate){this.showDailyResult();return;}rewardsPanel.call(this);const host=$('modal-card');host.classList.add('victory-card');host.querySelector('.timer-result')?.remove();if(this.stars<3){const p=document.createElement('p');p.className='star-advice';p.textContent=[this.hints>0?TEXT.starHintAdvice:'',this.wiltCount>0?TEXT.starWiltAdvice:'',this.timePenalty?TEXT.timerContinued:''].filter(Boolean).join(' ');host.insertBefore(p,host.querySelector('.garden-tip')||host.lastChild);}const harvest=document.createElement('p');harvest.className='basket-reward';harvest.setAttribute("aria-label",fmt(TEXT.basketAdded,{n:this.harvestAdded||0}));harvest.innerHTML=`<span class="harvest-plaque" aria-hidden="true"><span class="harvest-amount">${this.harvestAdded||0}</span></span><span aria-hidden="true">${TEXT.harvested}</span>`;host.insertBefore(harvest,host.lastChild);fitBasketCount(harvest.querySelector('.harvest-amount'),this.harvestAdded||0);
 if(Settings.data.timer&&this.challengeClock.started)this.appendTimeResult(host,String(this.level));const announce=(this.newUnlocks||[]).filter(n=>n==='daily4'||LoadedAssets.has({10:'deco_bench',25:'deco_scarecrow',45:'deco_pond'}[n]));if(announce.length){const p=document.createElement('p');p.className='unlock-note';p.textContent=announce.map(n=>unlockText(n)).join(' ');host.insertBefore(p,host.lastChild);}themeDOM();};
function unlockText(n){return TEXT[{6:'unlockDaily',daily4:'unlockDaily',10:'unlockBench',25:'unlockScarecrow',45:'unlockPond'}[n]];}
function timeResultLabel(seconds,previousBest,newBest=false){return (TEXT.timeLabel||'Time')+' '+timeText(seconds)+(Number.isFinite(previousBest)?' · '+(TEXT.bestLabel||'Best')+' '+timeText(previousBest):'')+(newBest?' · '+TEXT.newBest:'');}
