const rewardsBind=Game.prototype.bindDOM;Game.prototype.bindDOM=function(){rewardsBind.call(this);document.querySelector('.topbar .basket-button')?.remove();if(this.dailyDate){$('level-number').textContent=fmt(TEXT.dailyNumber,{n:DailyGarden.number(this.dailyDate)});$('level-name').textContent=TEXT.dailyGarden;}document.querySelector('.rule-strip')?.remove();const ruleButton=document.createElement('button');ruleButton.className='compact-rules';ruleButton.textContent=TEXT.rulesButton;ruleButton.onclick=()=>this.showRules();$('mobile-controls').append(ruleButton);};
const portraitRuleDown=Game.prototype.down;Game.prototype.down=function(...args){const result=portraitRuleDown.apply(this,args);if(this.drag?.pick)syncSeedRuleLine(this,this.drag.pick.type);return result;};
Game.prototype.showRuleTip=function(type,button){if(isPriorityPortrait()){syncSeedRuleLine(this,type);return;}this.ruleTipDismiss?.();const tip=document.createElement('div');tip.className='rule-tap-bubble';tip.setAttribute('role','status');tip.textContent=TEXT.rule[type];document.body.append(tip);skinElement(tip,'ui_bubble',.15);const strip=button.closest('.seed-drawer')||button,b=strip.getBoundingClientRect(),r=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(innerWidth-r.width-8,b.left+b.width/2-r.width/2))+'px';tip.style.top=Math.max(4,b.top-r.height-6)+'px';this.ruleTip=tip;const clear=()=>{tip.remove();clearTimeout(this.ruleTipTimer);document.removeEventListener('pointerdown',clear,true);if(this.ruleTip===tip)this.ruleTip=null;if(this.ruleTipDismiss===clear)this.ruleTipDismiss=null;};this.ruleTipDismiss=clear;this.ruleTipTimer=setTimeout(clear,3000);setTimeout(()=>{if(tip.isConnected)document.addEventListener('pointerdown',clear,true);},0);};
