 const wasDefault=this.note===TEXT.instruction,oldNote=this.note,oldText={...TEXT},mapScroll=this.mapViewport?.scrollTop||0,world=this.worldScreen?.classList.contains('map-screen')?'map':this.worldScreen?'home':null;
 const harvestIndex=oldText.harvestMessages.indexOf(this.harvestMessage);window.GardenI18n.save(code);window.GardenI18n.apply(TEXT,code);if(harvestIndex>=0)this.harvestMessage=TEXT.harvestMessages[harvestIndex];this.clearHint();this.hideBubble();this.ruleTipDismiss?.();
